$(function() {
	$("header").height($(window).height());
	
	dockEvent();
	$(window).bind("resize", function(e) {
		$("header").height($(window).height());
		setArtlist();
		setArtshow();
		setCaselist();
	});
    var mobileMenu = window.matchMedia('(max-width: 1100px)');
    var layoutState = window.NuliBlogLayoutState;
    var menuButton = $('.toolbar .homelink');
    var sidebar = $('body > header').attr('id', 'site-navigation');
    var backdrop = $('<button type="button" class="nav-backdrop" aria-label="关闭导航"></button>').appendTo('body').attr('tabindex', '-1');
    menuButton.attr({role:'button', tabindex:'0', 'aria-controls':'site-navigation', 'aria-label':'切换导航'});
    function setMenu(open, restoreFocus, focusMenu, persist) {
        if (persist && layoutState) layoutState.setMenu(open);
        document.documentElement.classList.toggle("nav-expanded", open);
        $('header, .toolbar, section.content').toggleClass('active', open);
        $('body').toggleClass('nav-open', open);
        menuButton.attr('aria-expanded', String(open));
        $('.toolbar .switch').toggleClass('glyphicon-th-list', !open).toggleClass('glyphicon-chevron-left', open);
        sidebar.prop('inert', mobileMenu.matches && !open).attr('aria-hidden', mobileMenu.matches && !open ? 'true' : 'false');
        if (mobileMenu.matches && open && focusMenu !== false) sidebar.find('a').first().trigger('focus');
        if (restoreFocus) menuButton.trigger('focus');
    }
    document.addEventListener('NuliBlog:nav-set', function(e) {
        if (e.detail && typeof e.detail.open === 'boolean') setMenu(e.detail.open, false, false, Boolean(e.detail.persist));
    });
    menuButton.on('click', function(e) {
        e.preventDefault();
        var open = !$('body').hasClass('nav-open');
        setMenu(open, false, true, true);
    }).on('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); $(this).trigger('click'); }
    });
    backdrop.on('click', function() { setMenu(false, true, false, true); });
    $(document).on('keydown.NuliBlogNav', function(e) {
        if (!mobileMenu.matches || !$('body').hasClass('nav-open')) return;
        if (e.key === 'Escape') { setMenu(false, true, false, true); return; }
        if (e.key === 'Tab') {
            var links = sidebar.find('a, button, input, [tabindex="0"]').add(menuButton).filter(':visible');
            var first = links.first()[0], last = links.last()[0];
            if (!first) return;
            if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
            else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        }
    });
    sidebar.on('click', 'a[href]', function() {
        if (mobileMenu.matches && $(this).attr('href').charAt(0) !== '#') setMenu(false, false);
    });
    function breakpointChanged() {
        var open = layoutState ? layoutState.getMenu() : !mobileMenu.matches;
        setMenu(open, false, false);
    }
    if (mobileMenu.addEventListener) mobileMenu.addEventListener('change', breakpointChanged);
    else mobileMenu.addListener(breakpointChanged);
    breakpointChanged();
    $('.words table').wrap('<div class="table-scroll" tabindex="0" role="region" aria-label="表格，可横向滚动"></div>');
    function syncToolbarHeight() {
        var height = $('.toolbar').outerHeight();
        if (height > 0) document.documentElement.style.setProperty('--toolbar-height', height + 'px');
    }
    if (window.ResizeObserver && $('.toolbar').length) new ResizeObserver(syncToolbarHeight).observe($('.toolbar')[0]);
    $(window).on('resize.NuliBlogToolbar', syncToolbarHeight);
    syncToolbarHeight();
    $(window).on("load.NuliBlogToolbar", syncToolbarHeight);
	var _sa = ["m", "o", "c", ".", "u", "k", "w", "i", "y"];
	$(".toolbar .category").each(function(i, item) {
		if ($(item).find("a.btn-primary").length == 0) $(item).find("a:eq(0)").addClass("btn-primary")
	});
	$(".toolbar .btnList .btn").each(function(i, item) {
		if ($(item).attr("href").indexOf("javascript:") == 0) $(item).addClass("disabled")
	});
    var currentPath = location.pathname.replace(/\/$/, '') || '/';
    sidebar.find('nav a').each(function() {
        var target = new URL(this.href, location.href);
        if (target.origin === location.origin && (target.pathname.replace(/\/$/, '') || '/') === currentPath && target.search === location.search) {
            $(this).attr('aria-current', 'page').parent().addClass('active');
        }
    });
    $('.qzPagination').attr({'role':'navigation', 'aria-label':'分页'});
    $('.qzPagination .now-page').attr('aria-current','page');
    function compactMobilePaging() {
        if (!mobileMenu.matches) return;
        $('#Paging .qzPagination').each(function() {
            var bar = this, items = $(bar).children();
            var current = parseInt($(bar).find('.now-page').first().text(), 10);
            if (!current) return;
            var numbered = [], previous = [], next = [];
            items.each(function() {
                var text = $.trim($(this).text());
                $(this).addClass('mobile-page-hidden');
                if (/^\d+$/.test(text)) numbered.push({node:this, page:parseInt(text,10)});
                else if (/^(?:‹|«|<|上一页|前一页)$/.test(text)) previous.push(this);
                else if (/^(?:›|»|>|下一页|后一页)$/.test(text)) next.push(this);
            });
            var max = numbered.reduce(function(n, item) { return Math.max(n, item.page); }, current);
            var first = Math.max(1, current - 1), last = Math.min(max, first + 2);
            first = Math.max(1, last - 2);
            var visible = numbered.filter(function(item) { return item.page >= first && item.page <= last; });
            visible.forEach(function(item) { $(item.node).removeClass('mobile-page-hidden'); });
            $(previous.slice(0,1).concat(next.slice(0,1))).removeClass('mobile-page-hidden');
            // Keep the current page and directional links even on unusually narrow screens.
            while (bar.scrollWidth > bar.clientWidth + 1 && visible.length > 1) {
                var removable = visible.filter(function(item) { return item.page !== current; });
                removable.sort(function(a,b) { return Math.abs(b.page-current)-Math.abs(a.page-current); });
                if (!removable.length) break;
                $(removable[0].node).addClass('mobile-page-hidden');
                visible = visible.filter(function(item) { return item !== removable[0]; });
            }
        });
    }
    compactMobilePaging();
    $(window).on('resize.NuliBlogPaging load.NuliBlogPaging', compactMobilePaging);


	$("section.content .words p").each(function(i, item) {
		if ($(item).css("text-align") == "center") $(item).css("text-align", "").attr("align", "center")
	});
	$("section.content .words img").each(function(i, item) {
		if ($(item).attr("border") == "1") $(item).css("border", "1px solid #ccc")
	});
	$(".caselist .items li a").prepend('<div class="shade"><u></u></div>').append('<div class="bg"><u></u></div>');
	$(".caselist .items li img, .artshow .words img").addClass("img-responsive");
	if ($("header").outerWidth() == 0) {
		$(".paging").css("margin-left", parseInt(($(window).width() - $(".qzPagination").width()) / 2))
	}
	$("#divCommentPost .cpost .glyphicon-plus").click(function(){
		$("#txaArticle").animate({ height: "+=100px" },300);
	})
	$("#divCommentPost .cpost .glyphicon-edit").click(function(){
		$("#txaArticle").val("").focus();
	})
});
function setArtlist() { /* Responsive CSS controls the layout. */ }

function setArtshow() { /* Responsive CSS controls the layout. */ }

function setCaselist() { /* Responsive CSS controls the layout. */ }

function dockEvent() {
	$(".dock").height($(".dock ul.icons li").length * 55 - 5);
	$(".dock ul.icons li i").bind("touchstart mouseenter click", function() {
		$(".dock ul.icons li").removeClass("active");
		$(this).parent().addClass("active")
	});
	$(".dock ul.icons li").bind("mouseleave", function() {
		$(".dock ul.icons li").removeClass("active")
	});
	$(".dock ul.icons li.up i").bind("click", function() {
		$("html,body").animate({
			scrollTop: 0
		}, 500)
	})
}
zbp.plugin.unbind("comment.reply", "system");
zbp.plugin.on("comment.reply", "default", function(id) {
	var i = id;
	$("#inpRevID").val(i);
	var frm = $('#divCommentPost'),
		cancel = $("#cancel-reply");

	if (!$('#temp-frm').length) frm.before($("<div id='temp-frm' style='display:none'>"));
    frm.addClass('reply-frm');
    var target = $('#cmt' + i);
    if (!target.length) target = $('#AjaxComment' + i);
    if (target.length) target.after(frm);

	cancel.show().off('click.NuliBlogReply').on('click.NuliBlogReply', function() {
		var temp = $('#temp-frm');
		$("#inpRevID").val(0);
		if (!temp.length || !frm.length) return;
		temp.before(frm);
		temp.remove();
		$(this).hide();
		frm.removeClass("reply-frm");
		return false;
	});
	try {
		$('#txaArticle').focus();
	} catch (e) {}
	return false;
});

zbp.plugin.on("comment.get", "default", function (logid, page) {
	$('span.commentspage').html("Waiting...");
	$.get(bloghost + "zb_system/cmd.php?act=getcmt&postid=" + logid + "&page=" + page, function(data) {
		$('#cancel-reply').trigger('click');
		$('#AjaxCommentBegin').nextUntil('#AjaxCommentEnd').remove();
		$('#AjaxCommentEnd').before(data);
		$("#cancel-reply").click();
	});
})

zbp.plugin.on("comment.postsuccess", "default", function () {
	$("#cancel-reply").click();
});
